function newsCard(n){const i=news.indexOf(n);return card(`<div class="news-card"><span class="meta">${esc(n.category)} · ${esc(n.date)}</span><h3><a href="article-${i}.html">${esc(n.title)}</a></h3><p>${esc(n.excerpt)}</p>${link('Читать ↗',`article-${i}.html`)}</div>`)}
function founderCard(name,role,image,copy,imageClass=''){return card(`<div class="founder-card"><div class="portrait portrait-photo ${imageClass}-frame"><img class="founder-portrait ${imageClass}" src="${image}" alt="${esc(name)}" /></div><div><span class="eyebrow">${esc(role)}</span><h3>${esc(name)}</h3><p>${esc(copy)}</p></div></div>`,'card founder-shell')}
function projectPage(slug){const p=projects.find(x=>x.slug===slug);if(!p)return '';const d=projectDetails[slug]||{audience:'Гостям, которым близка тема проекта и интересен обмен опытом.',topics:['знакомство с темой','практический разговор','обмен идеями'],results:['новый взгляд на тему','полезные знакомства','следующие шаги для себя']};const art=`assets/generated/project-${slug}.jpg`;return pageFrame(p.title,p.summary,`<div class="project-page-cover"><img src="${art}" alt="${esc(p.title)} — встреча и практика EVTENIA"/><div><span class="eyebrow">${esc(p.group)} · EVTENIA</span><p>${esc(p.summary)}</p></div></div><div class="grid grid-2 project-overview"><section class="card"><span class="eyebrow">Кому подойдёт</span><h2 class="section-title">Если вам близка эта тема</h2><p>${esc(d.audience)}</p><h3>С чем можно прийти</h3><ul class="project-points">${d.topics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="form-panel"><span class="eyebrow">Формат зависит от встречи</span><h2 class="section-title">Что даёт участие</h2><ul class="project-points">${d.results.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Даты, ведущих и условия конкретной встречи команда публикует отдельно. Уточните актуальный формат перед участием.</p>${link('Уточнить в MAX ↗',MAX_URL,'btn btn-green')}</section></div><section class="section"><div class="section-head"><div><span class="eyebrow">EVTENIA · ${esc(p.group)}</span><h2 class="section-title">О проекте</h2></div></div><div class="project-description"><p>${esc(p.description)}</p>${p.leadBio?`<p><strong>${esc(p.lead||'Ведущая направления')}.</strong> ${esc(p.leadBio)}</p>`:''}</div></section><section class="footer-cta"><div><span class="eyebrow">Следующий шаг</span><h2>Посмотрите афишу и выберите встречу</h2><p>Расписание и условия участия уточняйте в актуальном анонсе.</p></div>${link('Открыть афишу ↗','events.html','btn btn-green')}</section>`)}
function shagaemPage(){return pageFrame('Шагаем вместе','Коррекционный центр гармоничного развития «Шаги» · Пенза',`<div class="shagi-banner"><div class="shagi-logo-frame"><img src="assets/shagi-logo.jpeg" alt="Логотип коррекционного центра «Шаги»"/></div><div><span class="eyebrow">Коррекционный центр гармоничного развития</span><h2>Шаги</h2><p>Отдельный проект EVTENIA для семей с детьми от 2 до 17 лет.</p></div></div><div class="shaga-photo"><img src="assets/generated/project-shagaem.jpg" alt="Спокойная игровая среда для занятий и развития детей"/><p>Пространство, где движение и речь становятся частью общего маршрута развития.</p></div><div class="project-spotlight project-spotlight-wide"><div class="project-detail"><span class="eyebrow">Миссия центра</span><h2>Раскрываем потенциал ребёнка через гармонию движения и слова</h2><p class="formula">Движение + речь = успешный шаг</p><p>Центр рассматривает моторное и речевое развитие вместе. Специалисты объединяют свои наблюдения и выстраивают согласованный маршрут поддержки ребёнка.</p><p>Родителям важно не только решить отдельную задачу, но и понять, что влияет на развитие ребёнка и какие шаги помогут всей команде двигаться в одном направлении.</p><h3>С какими запросами обращаются</h3><div class="grid grid-3 project-support"><article class="card"><span class="index">Речь</span><h3>Речевое развитие</h3><p>ЗРР, ЗПР, алалия, дислексия и дизартрия.</p></article><article class="card"><span class="index">Движение и сенсорика</span><h3>Координация и особенности развития</h3><p>Неловкость, гипо- и гипертонус, СДВГ, РАС и дисграфия.</p></article><article class="card"><span class="index">Обучение</span><h3>Школьные трудности</h3><p>Невнимательность, сложности с почерком, чтением и счётом.</p></article></div><section class="section shagi-specialists"><div class="section-head"><div><span class="eyebrow">Команда центра</span><h2 class="section-title">Специалисты работают вместе</h2></div></div><p>Логопед, дефектолог, специалисты по адаптивной физкультуре, сенсорной интеграции и нейрокоррекции, детский и взрослый психологи, специалисты по ABA-терапии.</p></section><section class="section project-steps"><div class="section-head"><div><span class="eyebrow">Единый путь к результату</span><h2 class="section-title">Как строится работа</h2></div><p>По описанию команды центра в группе ВКонтакте.</p></div><div class="grid grid-2"><article class="card"><span class="index">01 · Диагностика</span><h3>Комплексно оценить развитие</h3><p>Специалисты изучают особенности ребёнка с разных сторон.</p></article><article class="card"><span class="index">02 · План команды</span><h3>Согласовать общую стратегию</h3><p>Команда объединяет наблюдения специалистов в единый план работы.</p></article><article class="card"><span class="index">03 · Занятия</span><h3>Работать над общими задачами</h3><p>Индивидуальные и парные занятия дополняют друг друга; специалисты обмениваются задачами.</p></article><article class="card"><span class="index">04 · Обратная связь</span><h3>Отслеживать динамику</h3><p>Раз в неделю команда анализирует прогресс, корректирует план и отправляет родителям видео с занятий.</p></article></div></section><div class="card project-contact"><span class="eyebrow">Центр «Шаги» · Пенза</span><h3>Запись и уточнение условий</h3><p>ул. Ленина, 16А · будни, 9:00–20:00</p><p><a href="tel:+79270988978">+7 (927) 098-89-78</a></p></div><div class="feature-cta project-actions">${link('Позвонить в центр','tel:+79270988978','btn btn-green')}${link('Открыть группу проекта ↗',COMMUNITY_URL)}<small>Актуальные сведения и записи — в официальной группе ВКонтакте.</small></div></div></div>`)}
function eventsPage(){const items=[['Открытые встречи','Знакомство с EVTENIA, участниками и направлениями сообщества.','about.html'],['Бизнес-встречи','Разговор о задачах, опыте, партнёрстве и развитии своего дела.','project-business.html'],['Образовательные форматы','Практические встречи и темы, которые помогают учиться через обмен опытом.','courses.html']];return pageFrame('Мероприятия EVTENIA','Открытые встречи, деловые знакомства и образовательные форматы.',`<div class="event-intro"><div><span class="eyebrow">Афиша сообщества</span><h2>Встречи, после которых есть о чём подумать и с кем продолжить разговор</h2><p>Расписание меняется. Перед поездкой или регистрацией проверьте дату, город и условия в официальных каналах EVTENIA.</p>${link('Уточнить ближайшую встречу в MAX ↗',MAX_URL,'btn btn-green')}</div><div class="event-photo"><img src="assets/generated/events-gathering.jpg" alt="Тёплая встреча сообщества за общим столом"/></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Форматы</span><h2 class="section-title">Выберите повод прийти</h2></div><p>Открывайте формат, который ближе к вашему запросу.</p></div><div class="grid grid-3">${items.map(([t,d,u])=>`<a class="card card-hover resource-card" href="${u}"><span class="index">EVTENIA · встречи</span><h3>${esc(t)} <span aria-hidden="true">↗</span></h3><p>${esc(d)}</p><span class="card-more">Подробнее</span></a>`).join('')}</div></section><div class="footer-cta"><div><span class="eyebrow">Актуальные даты</span><h2>Спросите о ближайшей встрече</h2><p>Точные даты и места размещаются в официальных каналах EVTENIA.</p></div>${link('Открыть ВКонтакте ↗',VK_URL,'btn btn-green')}</div>`)}
function storiesPage(){const values=[['Новые связи','Знакомства помогают находить людей со схожими интересами и продолжать разговор за пределами одной встречи.'],['Поддерживающее окружение','Можно обсуждать идеи, сомнения и планы в спокойной среде, где ценят уважительный диалог.'],['Практический обмен','Участники делятся своим опытом, задают вопросы и замечают новые варианты решения задач.'],['Повод действовать','Встреча может стать началом совместной инициативы, проекта или следующего шага в развитии.']];return pageFrame('Истории и ценности сообщества','Что люди приходят искать и создавать в EVTENIA.',`<div class="grid grid-2">${values.map(([t,d],i)=>`<article class="card story-card"><span class="index">0${i+1} · EVTENIA</span><h2>${esc(t)}</h2><p>${esc(d)}</p></article>`).join('')}</div><section class="footer-cta"><div><span class="eyebrow">Есть история про EVTENIA?</span><h2>Расскажите её команде</h2><p>Мы опубликуем личный отзыв только с согласия автора и после согласования текста.</p></div>${link('Написать в MAX ↗',MAX_URL,'btn btn-green')}</section>`)}
function partnersPage(){return pageFrame('Партнёры','Люди, организации и проекты, с которыми EVTENIA развивает совместные инициативы.',`<div class="grid grid-4 partner-grid">${partners.map(([name,url])=>`<a class="card card-hover resource-card partner-card" href="${url}"><span class="index">Партнёр EVTENIA</span><h3>${esc(name)} <span aria-hidden="true">↗</span></h3><span class="card-more">Открыть ресурс</span></a>`).join('')}</div><section class="section"><div class="section-head"><div><span class="eyebrow">Сотрудничество</span><h2 class="section-title">Предложить партнёрство</h2></div><p>Совместное событие, образовательный формат, экспертное участие или поддержка социальной инициативы.</p></div>${simpleForm('partner')}</section>`)}
function simpleForm(kind){const copy=kind==='partner'?'Коротко опишите вашу организацию, идею сотрудничества и удобный способ связи.':'Напишите, какой проект или формат вас интересует, в каком вы городе и как с вами связаться.';return `<div class="contact-prompt"><div><span class="eyebrow">Следующий шаг</span><h2>${kind==='partner'?'Обсудить сотрудничество':'Связаться с командой EVTENIA'}</h2><p>${copy}</p><p class="contact-note">Сайт не отправляет и не сохраняет заявки. Откройте чат и отправьте сообщение самостоятельно.</p></div><div class="contact-prompt-actions">${link('Написать в MAX ↗',MAX_URL,'btn btn-green')}${link('Открыть группу ВКонтакте ↗',COMMUNITY_URL,'text-link')}</div></div>`}
function contactsPage(){return pageFrame('Контакты','Напишите EVTENIA по вопросам участия, партнёрства и проектов.',`<div class="contact-layout"><div class="contact-tile"><span class="eyebrow">EVTENIA</span><h2>Связаться с командой</h2><p>Для вопросов о сообществе, событиях и сотрудничестве откройте официальный канал.</p>${link('Написать в MAX ↗',MAX_URL,'btn')}${link('Группа EVTENIA во ВКонтакте ↗',VK_URL)}</div><div class="card contact-project"><span class="eyebrow">Отдельный проект · Пенза</span><h2 class="section-title">Коррекционный центр «Шаги»</h2><p>ул. Ленина, 16А · будни, 9:00–20:00</p><p><a href="tel:+79270988978">+7 (927) 098-89-78</a></p>${link('Страница проекта ↗','project-shagaem-vmeste.html')}${link('Группа проекта во ВКонтакте ↗',COMMUNITY_URL)}</div></div><section class="section">${simpleForm('contact')}</section>`)}
function newsPage(){return pageFrame('Новости EVTENIA','Анонсы и материалы сообщества.',`<div class="empty-state news-empty"><span class="eyebrow">Лента сообщества</span><h2>Новых публикаций пока нет</h2><p>Проверяйте официальную группу: там появляются актуальные новости, даты и условия участия.</p>${link('Открыть группу EVTENIA ↗',VK_URL,'btn btn-green')}</div>`)}
function regionsPage(){return pageFrame('Регионы EVTENIA','Узнайте о направлениях и ближайших встречах в вашем городе.',`<div class="filterbar"><label>Поиск по городу <input id="region-search" type="search" placeholder="Например: Москва"/></label></div><div class="grid grid-2" id="regions-grid">${branches.map(b=>`<a class="card card-hover branch-card branch-card-link" href="region-${b.slug}.html"><div class="branch-art" data-city="${esc(b.city)}"></div><div class="branch-body"><span class="index">Региональное направление</span><h2>${esc(b.city)} <span aria-hidden="true">↗</span></h2><p>Локальные встречи и инициативы EVTENIA. Актуальные даты и места уточняйте перед участием.</p><span class="card-more">О регионе</span></div></a>`).join('')}</div>`)}
function branchPage(slug){const b=branches.find(x=>x.slug===slug);if(!b)return '';const city=b.city;return pageFrame(`EVTENIA · ${city}`,`Встречи и проекты сообщества в городе ${city}.`,`<div class="region-intro"><span class="eyebrow">Региональное сообщество</span><h2 class="section-title">EVTENIA в городе ${esc(city)}</h2><p>В каждом городе программа зависит от ближайших событий и инициатив участников. Напишите команде, чтобы узнать, что запланировано сейчас.</p>${link('Уточнить в MAX ↗',MAX_URL,'btn btn-green')}</div><section class="section"><div class="section-head"><div><span class="eyebrow">Направления сообщества</span><h2 class="section-title">С чего начать</h2></div></div>${projectCards(projects.slice(0,3))}</section>${link('Все регионы ↗','regions.html')}`)}
function teamPage(){return pageFrame('Команда','Основательницы EVTENIA.',`<div class="founder-grid">${founderCard('Евгения Викторовна Кислякова','Президент и сооснователь','assets/evgenia-cutout.png','Президент и сооснователь EVTENIA. Развивает социальные инициативы и объединяет людей вокруг проектов роста и взаимной поддержки.','portrait-cutout')}${founderCard('Светлана Иванчина','Сооснователь','assets/svetlana-armrest.png','Соосновательница EVTENIA. Развивает проекты организации и поддерживает совместные инициативы.','portrait-svetlana')}</div>`)}
function joinPage(){const ways=[['Прийти на встречу','Начните с открытого события и познакомьтесь с участниками и направлениями EVTENIA.','events.html'],['Выбрать проект','Найдите тему, которая откликается, и уточните у команды, как включиться.','about.html'],['Предложить инициативу','Расскажите идею и людей, которых она может объединить.','contacts.html']];return pageFrame('Вступить в EVTENIA','Выберите комфортный способ познакомиться с сообществом.',`<div class="grid grid-3">${ways.map(([t,d,u])=>`<a class="card card-hover resource-card" href="${u}"><span class="index">Ваш первый шаг</span><h3>${esc(t)} <span aria-hidden="true">↗</span></h3><p>${esc(d)}</p><span class="card-more">Перейти</span></a>`).join('')}</div><section class="section">${simpleForm('contact')}</section>`)}
function aboutPage(){return pageFrame('О EVTENIA','АНО по развитию социальных инициатив: проекты, встречи и люди, которые поддерживают рост друг друга.',`<div class="about-hero"><div><span class="eyebrow">Идея EVTENIA</span><h2>Создавать пространство, где знакомство становится возможностью действовать вместе</h2><p>EVTENIA объединяет клубные направления, медиапроекты, образовательные форматы и социальные инициативы. Здесь можно прийти на событие, найти близкую тему или предложить собственный проект.</p></div><img src="assets/generated/about-evtenia.jpg" alt="Открытое пространство сообщества для встреч и общения"/></div><section class="section"><div class="section-head"><div><span class="eyebrow">На чём строится сообщество</span><h2 class="section-title">Открытость, участие и развитие</h2></div></div><div class="grid grid-3">${[['Люди','В центре каждого проекта — общение, уважение и обмен опытом.'],['Инициативы','Участники могут предлагать идеи и объединяться вокруг общей задачи.'],['Практика','Встречи и направления помогают переводить интерес к развитию в конкретные шаги.']].map(([t,d],i)=>`<article class="card value-card"><span class="index">0${i+1} · EVTENIA</span><h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join('')}</div></section><section class="footer-cta"><div><span class="eyebrow">Начните знакомство</span><h2>Выберите свой формат участия</h2><p>Посмотрите проекты и ближайшие события.</p></div>${link('Проекты EVTENIA ↗','index.html#projects','btn btn-green')}</section>`)}
function galleryPage(){return pageFrame('Галерея EVTENIA','Детали встреч и моменты, из которых складывается атмосфера сообщества.',`<div class="gallery-feature"><img src="assets/generated/gallery-evtenia.jpg" alt="Цветы и детали подготовки к камерной встрече EVTENIA"/><div><span class="eyebrow">Сообщество EVTENIA</span><h2>Встречи, знакомства и новые идеи</h2><p>У каждой встречи свой характер: тема, пространство и небольшие детали, которые помогают гостям почувствовать себя частью сообщества. Фотоотчёты с реальных событий команда публикует в официальной группе.</p>${link('Смотреть фотоотчёты во ВКонтакте ↗',VK_URL,'btn btn-green')}</div></div>`)}
function servicePage(kind){const expert=kind==='expert';const title=expert?'Спроси эксперта':'Маркетинговая поддержка';const intro=expert?'Разберите конкретный рабочий или личный профессиональный вопрос с экспертом EVTENIA и определите, какие шаги можно проверить на практике.':'Соберите более ясное представление о своей аудитории, ценности предложения и способах рассказывать о нём.';const image=expert?'assets/generated/service-expert.jpg':'assets/generated/service-marketing.jpg';const imageAlt=expert?'Экспертная беседа за рабочим столом':'Обсуждение маркетинговой стратегии и материалов проекта';const blocks=expert?[['С какими вопросами приходят',['старт или развитие проекта, который упёрся в конкретную задачу','позиционирование, коммуникация с клиентами или командой','поиск следующего шага и взгляд со стороны практикующего специалиста']],['Как подготовиться',['кратко опишите ситуацию и желаемый результат','укажите, что уже пробовали и что не сработало','сформулируйте вопросы, на которые хотите получить ответ']],['Что можно унести с собой',['структурированный взгляд на задачу и дополнительные вопросы для проверки','варианты дальнейших действий и понимание, кому ещё стоит адресовать запрос','заметки и договорённости по итогам обсуждения; конкретный результат зависит от темы и формата']]]:[['Что можно разобрать',['для кого создан продукт, услуга или социальная инициатива','в чём ценность предложения и чем оно отличается для аудитории','какое сообщение и тон общения подходят проекту']],['Какие материалы обсудить',['сайт, презентацию, описание продукта или страницы в соцсетях','идеи публикаций, рубрики и контент для разных этапов знакомства','каналы продвижения и точки контакта с аудиторией']],['Возможные итоги',['сформулированные гипотезы об аудитории и позиционировании','структура ключевых сообщений и план ближайших коммуникаций','список приоритетов для самостоятельной работы или продолжения консультации']]];return pageFrame(title,intro,`<div class="service-detail"><img src="${image}" alt="${imageAlt}"/><div><span class="eyebrow">Услуги EVTENIA</span><h2>${esc(title)}</h2><p>${esc(intro)}</p><p>До начала команда уточнит запрос, доступность специалиста, формат, сроки и стоимость. Объём работы согласуется отдельно; показатели и бизнес-результаты заранее не гарантируются.</p></div></div>${blocks.map(([heading,items])=>`<section class="section service-section"><div class="section-head"><div><span class="eyebrow">${expert?'Спроси эксперта':'Маркетинговая поддержка'}</span><h2 class="section-title">${esc(heading)}</h2></div></div><div class="grid grid-3 service-cards">${items.map((item,i)=>`<article class="card service-info-card"><span class="index">0${i+1} · EVTENIA</span><p>${esc(item)}</p></article>`).join('')}</div></section>`).join('')}<div class="contact-prompt"><div><span class="eyebrow">Запросите условия</span><h2>Опишите задачу в сообщении</h2><p>Команда уточнит детали и сообщит, доступен ли такой формат сейчас.</p></div><div class="contact-prompt-actions">${link('Написать в MAX ↗',MAX_URL,'btn btn-green')}${link('Вернуться к услугам','services.html','text-link')}</div></div>`)}
function servicesPage(){const items=[['Спроси эксперта','Разберите рабочий вопрос с человеком, у которого есть подходящий опыт.','service-expert.html'],['Маркетинговая поддержка','Проясните аудиторию, сообщение и возможные каналы продвижения.','service-marketing.html'],['Предложить свою услугу','Расскажите, чем можете быть полезны сообществу и его участникам.','service-proposal.html']];return pageFrame('Услуги EVTENIA','Экспертный опыт, маркетинговая поддержка и предложения от участников сообщества.',`<div class="service-overview"><div><span class="eyebrow">Практическая поддержка</span><h2>От ясного запроса — к понятному следующему шагу</h2><p>Сначала команда знакомится с задачей, затем предлагает подходящий формат или помогает найти направление внутри сообщества. Состав, сроки и стоимость согласуются до начала работы.</p>${link('Обсудить запрос в MAX ↗',MAX_URL,'btn btn-green')}</div><img src="assets/service-planning.jpg" alt="Рабочая встреча и материалы для планирования"/></div><section class="section"><div class="section-head"><div><span class="eyebrow">Каталог</span><h2 class="section-title">Выберите направление</h2></div><p>Откройте карточку, чтобы узнать, с какими задачами можно прийти.</p></div><div class="grid grid-3">${items.map(([t,d,u])=>`<a class="card card-hover resource-card" href="${u}"><span class="index">Услуги EVTENIA</span><h3>${esc(t)} <span aria-hidden="true">↗</span></h3><p>${esc(d)}</p><span class="card-more">Подробнее</span></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Понятный процесс</span><h2 class="section-title">Как проходит обращение</h2></div></div><div class="grid grid-3">${[['01 · Запрос','Расскажите, какой результат вам нужен и что уже пробовали.'],['02 · Согласование','Команда уточнит, кто и в каком формате может помочь; обсудит условия заранее.'],['03 · Работа','Вы встречаетесь или работаете онлайн по согласованному плану и срокам.']].map(([t,d])=>`<article class="card process-card"><span class="index">${esc(t)}</span><p>${esc(d)}</p></article>`).join('')}</div></section>`)}
function proposalPage(){return pageFrame('Предложить свою услугу','Расскажите, чем ваш опыт и работа могут быть полезны участникам EVTENIA.',`<div class="service-detail"><img src="assets/generated/service-proposal.jpg" alt="Подготовка предложения о сотрудничестве и услуге"/><div><span class="eyebrow">Участие в сообществе</span><h2>Предложите экспертную услугу или формат</h2><p>EVTENIA рассматривает предложения специалистов и предпринимателей для встреч, совместных проектов и поддержки участников сообщества.</p><p>Перед публикацией или организацией команда знакомится с предложением, уточняет соответствие аудитории и обсуждает возможные условия напрямую.</p></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Что написать</span><h2 class="section-title">Подготовьте короткое описание</h2></div></div><div class="grid grid-2 service-cards"><article class="card service-info-card"><span class="index">01 · О вас</span><p>Имя, город, профессиональный опыт и удобный способ связи.</p></article><article class="card service-info-card"><span class="index">02 · Об услуге</span><p>Кому она подходит, какую задачу помогает решить и в каком формате проходит.</p></article><article class="card service-info-card"><span class="index">03 · Условия</span><p>Продолжительность, стоимость или диапазон цены, доступность и необходимые условия.</p></article><article class="card service-info-card"><span class="index">04 · Примеры</span><p>Ссылки на портфолио, сайт или примеры работ, если они помогают понять предложение.</p></article></div><div class="contact-prompt"><div><span class="eyebrow">Следующий шаг</span><h2>Отправьте предложение команде</h2><p>Первичное обсуждение не означает автоматическую публикацию или включение услуги в каталог. Возможность сотрудничества и условия согласуются отдельно.</p></div><div class="contact-prompt-actions">${link('Написать в MAX ↗',MAX_URL,'btn btn-green')}${link('Вернуться к услугам','services.html','text-link')}</div></div></section>`)}
function videoPage(slug){const v=videos.find(x=>x.slug===slug);if(!v)return '';return pageFrame(v.title,v.summary,`<div class="grid grid-2"><section class="card image-card"><div class="card-inner"><span class="eyebrow">Медиапроект EVTENIA</span><h2 class="section-title">${esc(v.title)}</h2></div></section><section class="card"><span class="eyebrow">Где смотреть</span><h2 class="section-title">Выпуски и анонсы</h2><p>${esc(v.summary)} Анонсы новых серий и видео доступны на площадках EVTENIA.</p>${link('Открыть канал Rutube ↗',RUTUBE_URL,'btn btn-green')}<p>${link('Новости проекта во ВКонтакте ↗',VK_URL)}</p></section></div>`)}
function coursesPage(){const items=[['Фитнес для мозга','Практики памяти, внимания и мышления, которые можно обсуждать и пробовать в повседневной жизни.','project-fitnes.html'],['Нетворкинг и деловое общение','Самопрезентация, полезные знакомства и поиск точек соприкосновения.','project-networking.html'],['Творческие форматы','Знакомство с идеями и практиками самовыражения в поддерживающем окружении.','project-creativity.html']];return pageFrame('Курсы и программы','Образовательные встречи EVTENIA и практические направления сообщества.',`<div class="course-overview"><img src="assets/course-workshop.jpg" alt="Рабочие материалы для занятия и творческой практики"/><div><span class="eyebrow">Учиться вместе</span><h2>Знания лучше приживаются, когда их можно обсудить и попробовать</h2><p>В EVTENIA образовательные форматы связаны с проектами и встречами. Конкретные программы, ведущие, даты и условия зависят от актуальной афиши.</p>${link('Спросить о расписании в MAX ↗',MAX_URL,'btn btn-green')}</div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Направления</span><h2 class="section-title">Выберите тему</h2></div><p>Откройте страницу направления и уточните ближайший формат участия.</p></div><div class="grid grid-3">${items.map(([t,d,u])=>`<a class="card card-hover resource-card" href="${u}"><span class="index">Практика EVTENIA</span><h3>${esc(t)} <span aria-hidden="true">↗</span></h3><p>${esc(d)}</p><span class="card-more">Подробнее</span></a>`).join('')}</div></section><div class="separate-project"><div class="shagi-logo-frame"><img src="assets/shagi-logo.jpeg" alt=""/></div><div><span class="eyebrow">Отдельный проект</span><h2>Шагаем вместе</h2><p>Коррекционный центр для детей и их семей. Запись и условия уточняются напрямую у центра.</p>${link('Открыть страницу проекта ↗','project-shagaem-vmeste.html','text-link')}</div></div>`)}
function faqPage(){return pageFrame('Частые вопросы','Ответы о вступлении и участии в EVTENIA.',`<div class="table-list">${[['Нужен ли опыт участия в клубах?','Нет, можно прийти впервые.'],['Как часто проходят мероприятия?','Расписание встреч публикуется в афише и соцсетях EVTENIA.'],['Можно ли стать партнёром?','Да, отправьте предложение через страницу партнёров.'],['Как присоединиться к проекту «Шагаем вместе»?','Откройте страницу проекта и перейдите в официальную группу VK.']].map(([q,a])=>card(`<h3>${esc(q)}</h3><p>${esc(a)}</p>`)).join('')}</div>`)}
function housingPage(){return pageFrame('Комитет по жилищной политике','Раздел о проектах, обсуждениях и инициативах комитета.',`<div class="grid grid-2">${card('<span class="eyebrow">О направлении</span><h3>Экспертные материалы и городские инициативы</h3><p>Здесь размещается информация о встречах и инициативах, связанных с жилищной политикой.</p>')}${card(`<span class="eyebrow">Сообщество</span><h3>Новости и обновления</h3><p>Актуальные новости комитета публикуются на странице ВКонтакте.</p>${link('Открыть VK ↗','https://vk.ru/committee_opora58','btn btn-green')}`)}</div>`)}
function legalPage(type){const privacy=type==='privacy';return pageFrame(privacy?'Политика конфиденциальности':'Согласие на обработку персональных данных','Правовая информация EVTENIA.',`<article class="card"><p><strong>Оператор:</strong> АВТОНОМНАЯ НЕКОММЕРЧЕСКАЯ ОРГАНИЗАЦИЯ ПО РАЗВИТИЮ СОЦИАЛЬНЫХ ИНИЦИАТИВ «ЕВТЕНИЯ», ОГРН 1265800002270, ИНН 5800021898.</p><h3>Общие положения</h3><p>${privacy?'Сайт EVTENIA показывает информацию о проектах, встречах и каналах связи. Формы для отправки и хранения заявок на сайте отключены.':'На сайте нет активной формы отправки заявки, поэтому согласие через веб-форму здесь не собирается. Если вы самостоятельно отправляете сообщение через MAX или ВКонтакте, его обработка зависит от выбранной площадки и адресата.'}</p><h3>Данные и цели обработки</h3><p>Могут обрабатываться имя, контактные данные и сведения, которые пользователь самостоятельно указывает в сообщении. Данные используются для ответа на запрос и организации участия в мероприятиях и проектах.</p><h3>Права пользователя</h3><p>Пользователь вправе запросить уточнение или удаление данных, а также отозвать согласие, связавшись с оператором по контактным каналам сайта.</p><p>По вопросам обработки данных напишите в <a href="${MAX_URL}">официальный канал MAX EVTENIA</a>.</p></article>`)}
function renderPage(key){if(key==='home')return homePage();if(key==='about')return aboutPage();if(key==='events'||key==='poster')return eventsPage();if(key==='stories')return storiesPage();if(key==='partners')return partnersPage();if(key==='contacts')return contactsPage();if(key==='news')return newsPage();if(key==='regions')return regionsPage();if(key==='team')return teamPage();if(key==='join')return joinPage();if(key==='gallery')return galleryPage();if(key==='services')return servicesPage();if(key==='service-expert')return servicePage('expert');if(key==='service-marketing')return servicePage('marketing');if(key==='service-proposal')return proposalPage();if(key==='courses')return coursesPage();if(key==='faq')return faqPage();if(key==='housing')return housingPage();if(key==='privacy'||key==='consent')return legalPage(key);if(key==='project-shagaem-vmeste')return shagaemPage();if(key.startsWith('project-'))return projectPage(key.slice(8));if(key.startsWith('video-'))return videoPage(key.slice(6));if(key==='region-penza')return branchPage('penza');if(key==='region-moscow')return branchPage('moscow');return `<div class="error-page"><span class="eyebrow">404</span><h1 class="page-heading">Страница не найдена</h1>${link('На главную ↗','index.html','btn btn-green')}</div>`}
function header(active){return `<header class="site-header"><div class="header-shell"><div class="topbar"><a class="brand" href="index.html"><span class="brand-star">✦</span><span><span class="brand-word">EVTENIA</span><span class="brand-sub">проекты для роста и развития</span></span></a><nav class="primary-nav" aria-label="Основная навигация">${primaryLinks.map(([t,u,k])=>`<a href="${u}" ${active===k?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="header-actions"><a class="social" href="${VK_URL}" aria-label="ВКонтакте">VK</a><a class="social" href="${MAX_URL}" aria-label="MAX">MAX</a><a class="social" href="${RUTUBE_URL}" aria-label="Rutube">▶ RUTUBE</a>${link('Подать заявку ↗','join.html','btn')}<button class="menu-toggle" aria-label="Открыть меню" aria-expanded="false">☰</button></div></div><div class="identity-band"><span class="name">EVTENIA</span><span class="identity-divider"></span><span class="description">АНО ПО РАЗВИТИЮ<br/>СОЦИАЛЬНЫХ ИНИЦИАТИВ</span></div><nav class="quick-nav" aria-label="Проектные разделы">${menuGroups.map((g,i)=>`<div class="menu-group"><button class="menu-trigger" type="button" aria-expanded="false">${esc(g.title)} <span class="chevron">⌄</span></button><div class="dropdown" hidden>${g.links.map(([label,url,kind])=>`<a class="${kind==='featured'?'dropdown-feature':''}" href="${url}">${kind==='featured'?'<img src="assets/shagi-logo.jpeg" alt="" loading="lazy"/>':''}<span>${esc(label)}</span></a>`).join('')}</div></div>`).join('')}</nav><div class="mobile-menu"><nav class="mobile-primary" aria-label="Основная навигация для мобильных">${primaryLinks.map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}<a href="join.html">Подать заявку ↗</a></nav><div class="mobile-social">${link('ВКонтакте ↗',VK_URL)}　${link('MAX ↗',MAX_URL)}　${link('Rutube ↗',RUTUBE_URL)}</div></div></div></header>`}
function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-star">✦</span><span><span class="brand-word" style="color:var(--pine);font-size:25px">EVTENIA</span><span class="brand-sub">проекты для роста и развития</span></span></a><p class="footer-about">Сообщество с проектными направлениями, региональными отделениями и единой афишей событий.</p></div><div class="footer-col"><h3>Навигация</h3>${[['Главная','index.html'],['Мероприятия','events.html'],['Регионы','regions.html'],['Новости','news.html'],['Команда','team.html'],['Галерея','gallery.html']].map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div><div class="footer-col"><h3>Участие</h3>${[['Подать заявку','join.html'],['Партнёрство','partners.html'],['Контакты','contacts.html'],['Услуги','services.html'],['Курсы/программы','courses.html'],['Шагаем вместе','project-shagaem-vmeste.html'],['FAQ','faq.html']].map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div><div class="footer-col"><h3>Документы и соцсети</h3>${[['Политика конфиденциальности','privacy.html'],['Согласие на обработку данных','consent.html'],['ВКонтакте',VK_URL],['MAX',MAX_URL],['Rutube',RUTUBE_URL]].map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div></div><div class="footer-bottom"><span>© EVTENIA · 2026</span><span>АНО по развитию социальных инициатив «Евтения»</span></div></div></footer><aside class="cookie" id="cookie" hidden><span>Мы используем cookies для улучшения работы сайта. Продолжая пользоваться сайтом, вы соглашаетесь с политикой конфиденциальности.</span><button class="btn" id="cookie-ok">Понятно</button></aside>`}
function init(){const root=document.querySelector('#app');const key=root.dataset.page||'home';const titleMap={home:'EVTENIA — клуб для всех, события и развитие',events:'Мероприятия EVTENIA',stories:'Истории участников EVTENIA',partners:'Партнёры EVTENIA',contacts:'Контакты EVTENIA',news:'Новости и блог EVTENIA',regions:'Регионы EVTENIA',team:'Команда EVTENIA',join:'Вступить в EVTENIA'};root.innerHTML=`${header(key)}<main class="page-shell"><div class="page-content">${renderPage(key)}</div></main>${footer()}`;const pageTitle=titleMap[key]||root.querySelector('.page-heading')?.textContent||'EVTENIA';document.title=key==='home'?pageTitle:`${pageTitle} — EVTENIA`;root.querySelectorAll('a[href^="http://"],a[href^="https://"]').forEach(a=>{a.target='_blank';a.rel='noopener noreferrer'});
let menuCloseTimer;const closeMenus=()=>document.querySelectorAll('.menu-group').forEach(g=>{g.classList.remove('is-open');g.querySelector('.menu-trigger').setAttribute('aria-expanded','false');g.querySelector('.dropdown').hidden=true});document.querySelectorAll('.menu-trigger').forEach(btn=>{btn.addEventListener('click',()=>{const group=btn.closest('.menu-group'),wasOpen=group.classList.contains('is-open');closeMenus();if(!wasOpen){group.classList.add('is-open');btn.setAttribute('aria-expanded','true');group.querySelector('.dropdown').hidden=false}});btn.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();btn.click();btn.closest('.menu-group').querySelector('.dropdown a')?.focus()}})});document.addEventListener('click',e=>{if(!e.target.closest('.menu-group'))closeMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenus()});document.querySelectorAll('.menu-group').forEach(g=>{g.addEventListener('mouseenter',()=>{clearTimeout(menuCloseTimer);if(matchMedia('(min-width:781px)').matches){closeMenus();g.classList.add('is-open');g.querySelector('.menu-trigger').setAttribute('aria-expanded','true');g.querySelector('.dropdown').hidden=false}});g.addEventListener('mouseleave',()=>{if(matchMedia('(min-width:781px)').matches){menuCloseTimer=setTimeout(()=>{g.classList.remove('is-open');g.querySelector('.menu-trigger').setAttribute('aria-expanded','false');g.querySelector('.dropdown').hidden=true},180)}})});
const toggle=document.querySelector('.menu-toggle'),mobile=document.querySelector('.mobile-menu');toggle?.addEventListener('click',()=>{const open=mobile.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'×':'☰'});document.querySelectorAll('.mobile-menu a').forEach(a=>a.addEventListener('click',()=>mobile.classList.remove('open')));
const cookie=document.querySelector('#cookie');if(!localStorage.getItem('evtenia-cookie'))cookie.hidden=false;document.querySelector('#cookie-ok')?.addEventListener('click',()=>{localStorage.setItem('evtenia-cookie','accepted');cookie.hidden=true});document.querySelectorAll('.local-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();form.querySelector('.form-feedback').textContent='Заявка с сайта не отправляется. Напишите нам в <a href="https://vk.ru/im/channels/-237168258" target="_blank" rel="noopener noreferrer">MAX</a>.';form.querySelector('.form-feedback').style.color='var(--pine)'}));
document.querySelectorAll('.news-filter').forEach(btn=>btn.addEventListener('click',()=>{const current=btn.dataset.category;document.querySelectorAll('.news-filter').forEach(b=>b.classList.toggle('btn-green',b===btn));const list=current==='Все'?news:news.filter(n=>n.category===current);document.querySelector('#news-grid').innerHTML=list.map(n=>newsCard(n)).join('')}));document.querySelector('#region-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#regions-grid .branch-card').forEach((card,i)=>card.hidden=!branches[i].city.toLowerCase().includes(q))});}
document.addEventListener('DOMContentLoaded',init);
